solution:
pub type Book = { title: Str; author: Str; pages: Int; }

impl Default for Book {
  fn default() -> Book {
    return Book{ title: "untitled", author: "unknown", pages: 0 };
  }
}

fn main() -> Int {
  let mut b = Book::default();
  b.title = "XIOM Guide";
  b.pages = 200;
  let c = b;  // Move
  return c.pages;
}
